import numpy as np, math
from collections import Counter
# rect = color whose bbox (Hb,Wb) matches out dims under ceil-split; dots = other color.
def solve(inp):
    arr=np.array(inp); flat=Counter(arr.flatten()); bg=flat.most_common(1)[0][0]
    others=[c for c in flat if c!=bg]
    # find rect color: color with bbox closest to a square-ish block pattern; try both choices of scat and rect per pair
    best=None
    for rc in others:
        Z=np.argwhere(arr==rc); r0,r1=int(Z[:,0].min()),int(Z[:,0].max()); c0,c1=int(Z[:,1].min()),int(Z[:,1].max())
        Hb,Wb=r1-r0+1,c1-c0+1
        if Hb<=Wb:
            for k in [2,3]:
                oh,Hb_=Hb/k if k else None; ow=Wb/k if k else None
                for s in (math.ceil(Hb/oh),math.ceil(Wb/ow)):
                    OH=(Hb+s-1)//s; OW=(Wb+s-1)//s
                    return dict(rc=rc,OH=OH,OW=OW,s=s,r0=r0,r1=r1,c0=c0,c1=c1)
    return None
for n in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    inp=G[n+' input']; out=np.array(G[n+' output'])
    d=solve(inp)
