# Function: given input I, produce downsampled grid using union bbox of rect color cells,
# divided into 4x4 blocks; cell = scatter color if block uniform rect-color else bg color.
def solve(I, rectColor, scColor, bgColor):
    mask=(I==rectColor); ys,xs=np.where(mask)
    r0,r1,c0,c1=ys.min(),ys.max(),xs.min(),xs.max()
    H=int(math.ceil((r1-r0+1)/4)); W=int(math.ceil((c1-c0+1)/4))
    res=[]
    for i in range(H):
        row=[]
        for j in range(W):
            blk=I[r0+i*4:r0+(i+1)*4, c0+j*4:c0+(j+1)*4]
            row.append(int(scColor if np.all(blk==rectColor) else bgColor))
        res.append(row)
    return np.array(res)

