            elif rule == 'least_freq_nonbg':
                others = [c for c, v in cnt.items() if c != bg and v > 0]
                row.append(min(others, key=lambda c: cnt[c])) if others else row.append(bg)
            elif rule == 'has_rare':
                rare = min((c for c, v in cnt.items() if c != bg), key=lambda c: cnt[c])
